import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"Day 12: Static & Dynamic Shared Libraries","description":"","frontmatter":{},"headers":[],"relativePath":"day12-static-and-dynamic-shared-libraries.md","filePath":"day12-static-and-dynamic-shared-libraries.md"}'),o={name:"day12-static-and-dynamic-shared-libraries.md"};function r(n,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="day-12-static-dynamic-shared-libraries" tabindex="-1">Day 12: Static &amp; Dynamic Shared Libraries <a class="header-anchor" href="#day-12-static-dynamic-shared-libraries" aria-label="Permalink to &quot;Day 12: Static &amp; Dynamic Shared Libraries&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Distinguish between static (<code>.a</code>) and dynamic (<code>.so</code>) libraries in Linux</li><li>Write a Yocto recipe that compiles and packages a dynamic shared library</li><li>Fix the <code>non-symlink .so</code> QA error when packaging unversioned libraries</li><li>Understand how <code>ALLOW_EMPTY</code> forces the creation of package groups</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day11-package-splitting-and-installed-vs-shipped.html">Day 11: Package Splitting &amp; Installed-vs-Shipped</a></li></ul></div><hr><h2 id="_1-static-vs-dynamic-libraries" tabindex="-1">1. Static vs. Dynamic Libraries <a class="header-anchor" href="#_1-static-vs-dynamic-libraries" aria-label="Permalink to &quot;1. Static vs. Dynamic Libraries&quot;">​</a></h2><p>When you write a C application, you often rely on external code (like <code>printf</code> from <code>glibc</code> or image parsing from <code>libpng</code>).</p><ul><li><strong>Static Libraries (<code>.a</code>)</strong>: The external code is copied directly into your final executable binary during the linking phase. Your binary becomes large, but it is standalone.</li><li><strong>Dynamic Shared Libraries (<code>.so</code>)</strong>: The external code remains in a separate file on the filesystem (e.g., <code>/usr/lib/libpng.so</code>). When your application runs, the Linux OS dynamically loads the library into memory. Multiple applications can share the exact same <code>.so</code> file in RAM, saving massive amounts of memory and disk space.</li></ul><p>Embedded Linux systems almost exclusively use <strong>Dynamic Shared Libraries</strong> to conserve storage and RAM.</p><hr><h2 id="_2-packaging-shared-libraries-in-yocto" tabindex="-1">2. Packaging Shared Libraries in Yocto <a class="header-anchor" href="#_2-packaging-shared-libraries-in-yocto" aria-label="Permalink to &quot;2. Packaging Shared Libraries in Yocto&quot;">​</a></h2><p>Let&#39;s assume you write a recipe that compiles <code>libmylib.so</code> and installs it to <code>/usr/lib/</code>.</p><p>According to Yocto&#39;s default package splitting rules (from Day 11):</p><ul><li><code>libmylib.so.1.0</code> (The actual binary) -&gt; Goes into <code>${PN}</code></li><li><code>libmylib.so.1</code> (Symlink to binary) -&gt; Goes into <code>${PN}</code></li><li><code>libmylib.so</code> (Symlink used during compile-time) -&gt; Goes into <code>${PN}-dev</code></li></ul><p>This default behavior is designed for <em>versioned</em> libraries (libraries that have <code>.1.0</code> appended to them).</p><h3 id="the-unversioned-library-problem" tabindex="-1">The Unversioned Library Problem <a class="header-anchor" href="#the-unversioned-library-problem" aria-label="Permalink to &quot;The Unversioned Library Problem&quot;">​</a></h3><p>Sometimes, a poorly written Makefile will output an <em>unversioned</em> library: <code>libmylib.so</code> (with no <code>.1.0</code> suffix). It is the actual binary, not a symlink.</p><p>If you install <code>libmylib.so</code>, Yocto&#39;s default rules see the <code>.so</code> extension and aggressively shove it into the <code>${PN}-dev</code> package.</p><p>When you install your main package (<code>${PN}</code>) onto the target board, it will be missing the library! Even worse, BitBake will throw a QA error.</p><h3 id="example-qa-error" tabindex="-1">Example QA Error <a class="header-anchor" href="#example-qa-error" aria-label="Permalink to &quot;Example QA Error&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ERROR: QA Issue: -dev package contains non-symlink .so: </span></span>\n<span class="line"><span>mylibrary-dev path &#39;/work/.../packages-split/mylibrary-dev/usr/lib/libmylib.so&#39;</span></span></code></pre></div><h3 id="the-fix" tabindex="-1">The Fix <a class="header-anchor" href="#the-fix" aria-label="Permalink to &quot;The Fix&quot;">​</a></h3><p>You must explicitly tell Yocto to pull <code>.so</code> files out of the <code>-dev</code> package and put them back into the main package.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In your recipe.bb</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Force the main package to take the .so file</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FILES:$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{PN}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">libdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/lib*.so&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Prevent the -dev package from stealing it back</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FILES:$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{PN}</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-dev:remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">libdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/lib*.so&quot;</span></span></code></pre></div><p><em>(Note: <code>${libdir}</code> evaluates to <code>/usr/lib</code>)</em></p><hr><h2 id="_3-library-only-recipes-allow-empty" tabindex="-1">3. Library-Only Recipes &amp; <code>ALLOW_EMPTY</code> <a class="header-anchor" href="#_3-library-only-recipes-allow-empty" aria-label="Permalink to &quot;3. Library-Only Recipes &amp; `ALLOW_EMPTY`&quot;">​</a></h2><p>If you write a recipe that <em>only</em> produces a library (<code>.so</code>) and headers (<code>.h</code>), it won&#39;t produce any standard binaries (<code>/usr/bin/</code>).</p><p>Yocto has a strict rule: <strong>If a package is completely empty, do not generate the <code>.ipk/.rpm</code> file.</strong></p><p>However, you might want to generate the empty <code>${PN}</code> package anyway, just so other recipes can depend on it logically. To bypass the rule, use <code>ALLOW_EMPTY</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Force BitBake to generate the mylibrary.rpm file even if it contains 0 files</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ALLOW_EMPTY:$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{PN}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span></span></code></pre></div><hr><h2 id="_4-hands-on-lab-exercises" tabindex="-1">4. Hands-On Lab Exercises <a class="header-anchor" href="#_4-hands-on-lab-exercises" aria-label="Permalink to &quot;4. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 12.1: Fix a Broken Library Recipe</p><ol><li>Create a recipe named <code>brokenlib_1.0.bb</code>.</li><li>Write a <code>do_compile</code> task that uses <code>gcc -shared -fPIC dummy.c -o libdummy.so</code> to generate an unversioned library.</li><li>Write a <code>do_install</code> task to install it into <code>${D}${libdir}</code>.</li><li>Try to build it: <code>bitbake brokenlib</code>. It will fail with the <code>non-symlink .so</code> QA error.</li><li>Apply the <code>FILES:${PN}</code> and <code>FILES:${PN}-dev:remove</code> fix from Section 2.</li><li>Rebuild and verify the error disappears.</li></ol></div><hr><h2 id="_5-further-reading" tabindex="-1">5. Further Reading <a class="header-anchor" href="#_5-further-reading" aria-label="Permalink to &quot;5. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Library Packaging Rules</td><td><a href="https://docs.yoctoproject.org/dev-manual/packages.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/packages.html#handling-library-packaging</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day11-package-splitting-and-installed-vs-shipped">← Day 11: Package Splitting</a><a href="/day13-recipe-dependencies-depends-rdepends">Day 13: Recipe Dependencies →</a></div>',38)])])}const y=a(o,[["render",r]]);export{b as __pageData,y as default};
